#!/usr/bin/env python3# -*- coding: utf-8 -*-"""原始訊號 ai0/ai1   ↓第一層 StreamingWindowAssembler：接尾巴、切成不重複的窗   ↓（窗）第二層 StreamingFeatureEngine：去DC → 濾波算特徵 → summary → rel/z → CUSUM → temporal   ↓（特徵表）第三層 StreamingRuntimeEngine：跑模型 → 每窗分數+0/1 → 管暖機   ↓（df_predictions）【出了這個檔案】inference_worker：alarm_buffer 跨批告警 → leak_status → 回傳前端# =============================================================================# runtime_streaming.py — 串流增量處理# =============================================================================## 【三層架構】##  第一層｜StreamingWindowAssembler#    職責：Raw Signal 接收 + 增量切窗#    ├── push(ai0, ai1)：加入新一批訊號，只回傳本批新產生的 Window#    ├── 與上一批尾端訊號拼接，依 hop_sec 向前滑動#    ├── 已輸出的 Window 不會重複輸出#    └── reset()：清除尾端訊號與 Window 編號##  第二層｜StreamingFeatureEngine#    職責：增量特徵工程（DC removal → Raw → rel/z → CUSUM → Temporal）#    ├── process_chunk(ai0, ai1)#    │     ├── 呼叫 StreamingWindowAssembler.push() 取得新 Window#    │     ├── _prepare_feature_windows()#    │     │     └── 每個 Window 去除 DC，建立 diff = ai1 - ai0#    │     ├── extract_required_window_features()#    │     │     └── 只算模型與規則真正需要的底層 Raw features#    │     ├── build_offband_summary_features()#    │     │     └── 建立頻帶群組 Summary 與 Ratio#    │     ├── _apply_fixed_baseline()#    │     │     └── 套用 site_baseline.json 的固定 mean/std → rel_ / z_#    │     ├── _update_cusum_features()#    │     │     └── 跨批次累積 CUSUM（pos / neg），保存上一批結尾狀態#    │     └── _update_temporal_features()#    │           └── 用最近 3～5 個 Window 歷史建立#    │               delta / delta_prevNmean / local_rel / local_z /#    │               rolling_std / rolling_slope / rolling_max_gap#    │#    ├── _build_required_extractor_features()#    │     └── 從模型與規則欄位反推底層需要的 Raw 欄位清單#    ├── _resolve_temporal_base_features()#    │     └── 從模型與規則欄位反推需要 Temporal 的 Raw 欄位清單#    └── reset()：清除切窗、CUSUM、Temporal 狀態（不清 Site Baseline）##  第三層｜StreamingRuntimeEngine#    職責：模型推論 + 暖機管理#    ├── process_chunk(ai0, ai1)#    │     ├── 呼叫 StreamingFeatureEngine.process_chunk()#    │     ├── run_model_inference() → 逐窗 leak_score / pred#    │     └── 回傳結果 dict（含 buffer_ready / calc_time_sec 等）#    ├── buffer_ready：elapsed_sec >= warmup_sec（預設 5 秒）#    │     暖機期間仍計算特徵與機率，不對前端發出正式告警#    └── reset()：清除特徵引擎 + 模型輸出狀態## =============================================================================# 【本引擎的邊界（到逐窗機率為止）】#    本引擎只負責到「每個 Window 的 leak_score / pred」。#    以下告警後處理不在此檔，改由 two_sensor_api_final2.py 的#    inference_worker 接手：#    - 維護最近 N 秒的 alarm_buffer（跨批滑動緩衝）#    - 對整個緩衝呼叫 _run_alarm_postprocess()：#        Two-stage / Veto / 最短告警持續時間#        → normal / disturbance_suspect / leak 最終狀態#    - 組成 API response 回傳前端# ============================================================================="""from __future__ import annotationsimport timeimport numpy as npimport pandas as pdfrom shared_feature_utils import (    extract_required_window_features,)from runtime_inference import (    resolve_runtime_band_groups,    build_offband_summary_features,    run_model_inference,)#                                                   ****************************************************#                                                        第一層：把一批一批進來的訊號,接成連續不重複的窗#                                                   ****************************************************#離線時你有一整段訊號,一次切窗很簡單。但串流是一批一批來的(每批 0.5 秒),而窗是 0.2 秒、每 0.05 秒滑一次。問題來了:# 一批 0.5 秒的訊號,結尾可能切到一半的窗(剩下的資料不夠湊一個完整 0.2 秒窗)# 下一批來的時候,得把上一批剩下的尾巴接上去,才能繼續切#class StreamingWindowAssembler:    """將分批收到的 Raw Signal 組成連續且不重複的 Window。"""    def __init__(        self,        *,        fs: float,                         # 取樣率 fs        window_sec: float,                 # 窗長        hop_sec: float,                    # 滑動步長        record_id: str = "live_stream",    # 串流的識別名    ):        self.fs = int(round(float(fs)))        self.window_sec = float(window_sec)        self.hop_sec = float(hop_sec)        self.record_id = str(record_id)        # 將秒數轉成整數樣本點數(設定 fs=1_000_000、window_sec=0.2、hop_sec=0.05)        self.window_samples = int(round(self.fs * self.window_sec))     # window_samples = 200,000(一個窗有 20 萬點)        self.hop_samples = int(round(self.fs * self.hop_sec))           # hop_samples = 50,000(每次往前滑 5 萬點)        # 相鄰 Window 重疊的 Raw Signal 長度。        # 因為窗長 20 萬、每次只滑 5 萬,所以連續兩個窗有 15 萬點是重疊的。        # 這個「尾巴」就是為什麼串流要保留上批資料——下一個窗需要用到這 15 萬點。        self.raw_tail_samples = (self.window_samples - self.hop_samples)        self.raw_tail_sec = (self.raw_tail_samples / self.fs)                # 檢查設定合不合理        self._validate_config()        self.reset()    # ====================    # 防呆檢查    # ====================    def _validate_config(self):        """確認切窗設定合理。"""        if self.fs <= 0:            raise ValueError("fs 必須大於 0")        if self.window_samples <= 0:            raise ValueError("window_sec 必須大於 0")        if self.hop_samples <= 0:            raise ValueError("hop_sec 必須大於 0")        # 滑動視窗不能比窗還長        if self.hop_samples > self.window_samples:            raise ValueError(                "hop_sec 不可大於 window_sec："                f"window_sec={self.window_sec}，"                f"hop_sec={self.hop_sec}"            )    # ====================    # 初始化/清空狀態    # ====================    def reset(self):        """        開始新的監測 Session。        因此重連 「reset」呼叫的就是這個——把這 5 個歸零,等於「忘掉之前的串流,從頭開始」        清除：        - 尚未使用的 Raw Signal        - Window 編號        - 串流時間軸        不會修改模型、Site Baseline 或設定檔。        """        # 「尾巴緩衝」。存還沒被切完、要留給下一批用的訊號。一開始是空的。        self.pending_ai0 = np.empty(0, dtype=np.float64,)        self.pending_ai1 = np.empty(0, dtype=np.float64,)                # 累計總共收到幾個點(拿來算 elapsed_sec「串流跑多久了」)        self.total_samples_received = 0                # 下一個窗要從第幾個點開始，是保證「窗不重複」的關鍵計數器        self.next_window_start_sample = 0                # 下一個窗的編號(0, 1, 2...),拿來給窗命名        self.next_window_index = 0    # 串流總共跑了幾秒(總點數 ÷ 取樣率)    @property    def elapsed_sec(self):        """目前總共收到幾秒訊號。"""        return (self.total_samples_received / self.fs)    # 目前尾巴還留著幾秒的資料    @property    def pending_sec(self):        """目前尾端尚保留多少秒 Raw Signal。"""        return (len(self.pending_ai0) / self.fs)    # ====================    # 每批訊號進來時，接尾巴 + 切出所有能切的完整窗    # ====================    def push(self,              ai0,       # 遠端感測器本次新增的 Raw Signal             ai1,):     # 近端感測器本次新增的 Raw Signal        """        加入一批新的雙通道訊號，只回傳新產生的 Window。        """        # 把輸入的訊號轉成一維 float64 陣列        ai0 = np.asarray(ai0, dtype=np.float64,).reshape(-1)        ai1 = np.asarray(ai1, dtype=np.float64,).reshape(-1)        # 檢查合法性(長度一致、沒有 NaN        self._validate_chunk(ai0, ai1,)        # 記錄實際收到的總樣本數。        self.total_samples_received += len(ai0)        # 接尾巴:把這批新訊號接到「上批剩下的尾巴」後面        self.pending_ai0 = np.concatenate([self.pending_ai0, ai0,])        self.pending_ai1 = np.concatenate([self.pending_ai1,ai1,])        new_windows = []        # 核心迴圈:只要 pending 裡的資料還夠切一個完整窗(≥ 20 萬點),就一直切。切不出完整窗了就停,剩下的留在 pending 當尾巴        while (len(self.pending_ai0) >= self.window_samples):            window_ai0 = self.pending_ai0[:self.window_samples].copy()            window_ai1 = self.pending_ai1[:self.window_samples].copy()            # 計算這個窗的時間座標            # tart_sample 用的是那個跨批計數器,所以時間軸是連續的,不會因為分批而亂。            start_sample = (self.next_window_start_sample)            end_sample = (start_sample + self.window_samples)            # 窗的起訖秒數            t_start = (start_sample / self.fs)            t_end = (end_sample / self.fs)            # 窗中心時間            t_ref = (t_start + t_end) / 2.0            # 把這個窗包成一個 dict 放進結果            new_windows.append(                {                    "filename": (                        f"{self.record_id}_"                        f"w{self.next_window_index:08d}"                    ),                    "record_id": self.record_id,                    "window_index": (self.next_window_index),                    "start_sample": start_sample,                    "end_sample": end_sample,                    "t_start": t_start,                    "t_end": t_end,                    "t_ref": t_ref,                    "fs": self.fs,                    "label": -1,          # 即時推論沒有真實答案，標 -1                    "meta": {},                    "signal": {           # 這裡先保留原始訊號, 去 DC 政策在下一層特徵工程處理。                        "ai0": window_ai0,                        "ai1": window_ai1,                    },                }            )            # 滑動：切完一個窗後,pending 往前丟掉 hop_samples(5 萬點),不是丟掉整個窗長。這就是重疊的來源——只前進 5 萬,剩下的 15 萬留著給下一個窗用。這是滑動窗的精髓            self.pending_ai0 = (self.pending_ai0[self.hop_samples:])            self.pending_ai1 = (self.pending_ai1[self.hop_samples:])                        # 更新跨批計數器:下一個窗的起點 +5 萬、編號 +1            self.next_window_start_sample += (self.hop_samples)            self.next_window_index += 1        return new_windows      # 回傳這批新產生的窗(可能是 0 個到好幾個)。已經輸出過的窗永遠不會再出現    # ====================    # 輸入檢查    # ====================    def _validate_chunk(self, ai0, ai1,):        """檢查每批新增資料是否可以安全加入串流。"""        # 非空        if len(ai0) == 0:            raise ValueError("新增訊號不可為空")                # 兩通道長度一致        if len(ai0) != len(ai1):            raise ValueError(f"ai0 與 ai1 長度不一致：ai0={len(ai0)}，ai1={len(ai1)}")        # 沒有 NaN/Inf        if not np.isfinite(ai0).all():            raise ValueError("ai0 含有 NaN 或 Inf")        # 沒有 NaN/Inf        if not np.isfinite(ai1).all():            raise ValueError("ai1 含有 NaN 或 Inf")            #                                                   ****************************************************#                                                     第二層：拿到切好的窗,讓每個窗變成一排數字(特徵),讓模型可讀#                                                   ****************************************************class StreamingFeatureEngine:    """    串流特徵工程引擎。        第一層切好的窗       ↓ ① _prepare_feature_windows   每窗去DC + 建 diff       ↓ ② extract_required_window_features   算底層 band 能量（濾波在這）       ↓ ③ build_offband_summary_features   把多個 band 併成 summary/ratio       ↓ ④ _apply_fixed_baseline   用固定基準算 rel_/z_       ↓ ⑤ _update_cusum_features   跨批累積 CUSUM       ↓ ⑥ _update_temporal_features   用最近幾窗歷史算 delta/rolling       ↓ ⑦ 檢查模型/規則要的欄位都齊了    回傳 df（每窗一列，欄位齊全）    負責：    1. 建立本批新增 Window。    2. 對每個 Window 去除 DC。    3. 建立 ai0、ai1 與 diff。    4. 只計算模型與規則必要的底層 Raw features。    5. 建立頻帶群組 Summary 與 Ratio。    6. 使用固定 Site Baseline 建立 rel/z。    7. 跨批次更新 CUSUM。    8. 跨批次更新 Temporal features。    不負責：    - 模型機率預測    - Two-stage／Veto 告警判斷    - API 與前端資料回傳    """    # 建立摘要類的欄位名    SUMMARY_BASE_COLUMNS = [        "offband_E_mean",        "offband_E_max",        "leak_focus_E_mean",        "leak_focus_E_max",        "resonance_E_mean",        "resonance_E_max",    ]    # ====================    # 從「模型需要的特徵」反推出「底層要算哪些東西」    # ====================    def __init__(        self,        *,        runtime_cfg,        record_id="live_stream",    ):        self.runtime_cfg = runtime_cfg        self.record_id = str(record_id)        # 呼叫第一層(切窗器)增量切窗器。        self.window_assembler = (            StreamingWindowAssembler(                fs=runtime_cfg["fs"],                window_sec=runtime_cfg["window_sec"],                hop_sec=runtime_cfg["hop_sec"],                record_id=self.record_id,            )        )        # 將正式 Band Config 整理成底層        # feature extractor 使用的頻帶組合。        self.band_groups = (resolve_runtime_band_groups(runtime_cfg["band_config"]))        # 模型特徵反推得到的必要 Raw features。        self.raw_base_features = list(runtime_cfg["raw_base_features"])                # 真正需要建立 CUSUM 的 z 特徵。        self.z_base_features = list(runtime_cfg["z_base_features"])                # 正式模型使用的最終特徵。        self.model_feature_names = list(runtime_cfg["model_feature_names"])                # 正式規則需要的欄位，供後面的 Temporal 依賴解析會讀取它。        self.rule_feature_names = list(runtime_cfg["rule_feature_names"])                # 反推底層Extractor需要計算的Raw欄位 → 決定②要濾哪些 band        self.required_extractor_features = (self._build_required_extractor_features())                        # 從模型與規則欄位反推，真正需要建立 Temporal 的 Raw features → 決定⑥要算誰        self.temporal_base_features = (self._resolve_temporal_base_features())                # 所有清單建立完成後，才能初始化跨批狀態(CUSUM/temporal 的記憶)        self._reset_derived_feature_state()        # 進固定的 baseline 統計(算 rel/z 要用)        self.baseline_stats = (runtime_cfg["site_baseline_payload"].get("feature_stats",{},))        # 確認 baseline 不是空的        if not self.baseline_stats:            raise ValueError("site_baseline.json 缺少 feature_stats")    @property    def elapsed_sec(self):        return (            self.window_assembler.elapsed_sec        )    @property    def raw_tail_sec(self):        return (            self.window_assembler.raw_tail_sec        )    # ====================    # 清空這一層的所有記憶    # ====================    def reset(self):        """        清除切窗、CUSUM 與 Temporal 狀態。        不會修改固定 Site Baseline。        """        # 呼叫第一層(切窗器)的 reset。        # 回想第一層的 reset 會清空:尾巴訊號 pending、窗計數器 next_window_start_sample、next_window_index。也就是「忘掉切窗的進度,從頭切」        self.window_assembler.reset()                # 清空這一層自己的衍生狀態(CUSUM + temporal 的記憶)        self._reset_derived_feature_state()    # ====================    # 主流程    # ====================    def process_chunk(        self,        ai0,        ai1,    ):        """        接收一批新增 Raw Signal，        回傳本批新增 Window 的基礎與 rel/z 特徵。        如果目前訊號不足一個完整 Window，        回傳空的 DataFrame。        """        # 第一層切窗：丟給內部第一層切窗        new_windows = ( self.window_assembler.push(ai0, ai1,))        # 如果這批訊號還不夠切一個完整窗,回空的 DataFrame -> 訊號不足時只累積、不出結果(第一層:訊號要湊滿 20 萬點才切得出一個窗)        if not new_windows:            return pd.DataFrame()        # ① 去DC + 建 diff:每個 Window 個別完成去 DC 與 diff。        feature_windows = (self._prepare_feature_windows(new_windows))        # ② 算底層 band 能量:只針對本批新產生的 Window，執行正式頻帶特徵計算。        feature_rows = (            extract_required_window_features(                feature_windows,                band_config=self.runtime_cfg["band_config"],                required_feature_names=(self.required_extractor_features),      # init 反推出來的那份清單,只算需要的                # 不同 Window 的 Raw 特徵可平行計算，CUSUM 與 Temporal 仍會在後面依時間順序更新。                n_jobs=6,                    verbose=False,            )        )        # feature_rows 是「每個窗一排特徵」,把它轉成表格 df(DataFrame)        df = pd.DataFrame(feature_rows)        # 如果空的 → 報錯        if df.empty:            raise ValueError("新增 Window 沒有產生任何特徵")        # 按時間 t_ref 排序(確保後面 CUSUM/temporal 是照時間順序)        df = df.sort_values("t_ref").reset_index(drop=True)        # ③ 併 summary/ratio:建立規則需要的頻帶群組摘要及比例。        # 把「12 個 scan band 的能量」併成 leak_focus_E_mean、把 offband 併成 offband_E_mean、算出它們的比例 offband_to_leak_focus_E_ratio        # 因為告警規則不是看單一 band,它要看的是整體對比        if self.runtime_cfg["include_offband_summary"]:     # 先檢查設定檔有沒有開啟這個功能(include_offband_summary)            df = build_offband_summary_features(df, self.runtime_cfg["band_config"],)        # ④ 算 rel_/z_：拿當前值,跟「正常基準」比,看差多少、差幾個標準差        # rel_xxx(相對值)= 當前值 − 正常平均。正的代表比正常高,負的代表比正常低。        # z_xxx(標準分數)= (當前值 − 正常平均) ÷ 正常標準差。代表「偏離正常幾個標準差」,超過 2、3 就很不尋常了。        # 先列出「哪些欄位要做 baseline」:對模型衍生特徵的必要 Raw 欄位套用固定 Site Baseline(site_baseline.json)。        baseline_input_columns = list( self.raw_base_features)        # 規則額外需要的摘要欄位:如果正式規則需要 summary 的 rel/z，也將對應摘要欄位加入 Baseline 輸入。        baseline_input_columns.extend(self._find_rule_baseline_inputs())        # 把這份清單 + 表 df 丟進 _apply_fixed_baseline        self._apply_fixed_baseline(df,baseline_input_columns,)                # ⑤ ⑥ 跨批狀態        # 依時間順序更新跨批次 CUSUM。        self._update_cusum_features(df)        # 依最近幾個 Window 的歷史，建立 Delta、Local 與 Rolling。        self._update_temporal_features(df)                # ⑦ 完整性檢查。確認模型要的、規則要的欄位都算出來了,缺任何一個直接報錯        missing_model_features = [feature_name            for feature_name in self.model_feature_names            if feature_name not in df.columns        ]        if missing_model_features:            raise ValueError(f"串流特徵缺少模型必要欄位：{missing_model_features[:20]}")                    # 規則欄位檢查:確認後處理規則需要的欄位也已經建立。        missing_rule_features = [feature_name            for feature_name in self.rule_feature_names            if feature_name not in df.columns        ]        if missing_rule_features:            raise ValueError(f"串流特徵缺少規則必要欄位：{missing_rule_features[:20]}")                return df    # ====================    # ① 去DC + diff    # ====================    def _prepare_feature_windows(        self,        windows,    ):        """        將增量切出的 Raw Window 整理成 shared_feature_utils 可使用的格式。        串流版在每個 Window 內去除 DC，再建立 diff = ai1 - ai0。        """        # 準備一個空清單 prepared 裝加工後的結果        prepared = []        # 每個窗做:去DC + 建 diff        for window in windows:      # windows 是第一層切好的一串窗            # 淺拷貝,避免改到原始的窗資料            item = dict(window)            item["signal"] = dict(window["signal"])            # 從窗裡把兩個通道的訊號拿出來(ai0 遠端、ai1 近端),確保是 float64 陣列            ai0 = np.asarray(item["signal"]["ai0"], dtype=np.float64,)            ai1 = np.asarray(item["signal"]["ai1"], dtype=np.float64,)            # 每個 Window 使用自己的平均值去 DC。            ai0_dc = (ai0 - np.mean(ai0))            ai1_dc = (ai1 - np.mean(ai1))            # 把去DC後的訊號寫回這個(複製的)窗            item["signal"]["ai0"] = ai0_dc            item["signal"]["ai1"] = ai1_dc            item["signal"]["diff"] = (ai1_dc - ai0_dc)     # 建第三通道 diff            prepared.append(item)        return prepared        # ====================    # 確保規則要用到的摘要 rel/z 也會被算到    # ====================    def _find_rule_baseline_inputs(self):        """        掃過規則要的欄位,找出「是摘要的 rel_/z_」的,把它們的底層名挑出來,補進 baseline 清單                來源1：raw_base_features:模型自己要的底層特徵(設定檔給的)        來源2：這個 method:規則額外要的摘要欄位        """        # 準備一個空清單,裝挑出來的欄位        required = []        # 逐欄檢查：rule_feature_names 是「告警規則需要的所有欄位名」        # 為什麼只管 rel_ 和 z_?因為只有這兩種是「需要 baseline 才能算出來」的(rel/z 是 baseline 的產物)。其他欄位(例如原始能量)不經過 baseline,不用挑        for feature_name in (self.rule_feature_names):              # 如果是 rel_ 開頭 → 去掉 rel_,留下底層名            if feature_name.startswith("rel_"):                raw_name = feature_name[len("rel_"):]            # 如果是 z_ 開頭 → 去掉 z_            elif feature_name.startswith("z_"):                raw_name = feature_name[len("z_"):]            # 都不是 → continue            else:                continue            # 去完前綴後,再檢查:這個底層名是不是摘要欄位            if (raw_name in self.SUMMARY_BASE_COLUMNS):                required.append(raw_name)        return required    # ====================    # 把特徵變成「跟正常比,差多少」    # ====================    def _apply_fixed_baseline(        self,        df,        feature_columns,    ):        """        使用 site_baseline.json 的固定 mean/std 建立 rel_* 與 z_*。        正式 Runtime 不允許使用當下資料重新估計 Baseline，也不使用 fallback。        """        eps = 1e-12        # 去除重複欄位，同時保留原順序。        feature_columns = list(dict.fromkeys(feature_columns))        # 逐個欄位處理        for column in feature_columns:            # ① 這個欄位在表裡存在嗎?            if column not in df.columns:                raise ValueError(f"新增 Window 缺少 Baseline 輸入欄位：{column}")            # ② 基準檔裡有這個欄位的統計嗎?            if (column not in self.baseline_stats):                raise ValueError(f"site_baseline.json 缺少必要特徵：{column}")                            # 從基準檔讀出這個欄位的正常平均 mean 和正常標準差 std            feature_stat = (self.baseline_stats[column])            baseline_mean = float(feature_stat.get("mean", np.nan,))            baseline_std = float(feature_stat.get("std", np.nan,))            # 防呆:平均和標準差不能是 NaN,標準差不能太接近 0            if not np.isfinite(baseline_mean):                raise ValueError(f"Baseline mean 無效：{column}")            if (not np.isfinite(baseline_std) or baseline_std < eps):                raise ValueError(f"Baseline std 無效：{column}")            # 欄位當前的值            values = pd.to_numeric(df[column], errors="coerce",)                        # rel_xxx = 當前值 − 正常平均            # z_xxx = (當前值 − 正常平均) ÷ 正常標準差(加 eps 防除0)            df[f"rel_{column}"] = (values - baseline_mean)            df[f"z_{column}"] = (values - baseline_mean) / (baseline_std + eps)                    # ====================    # 實際清空 CUSUM 和 temporal    # ====================             def _reset_derived_feature_state(self):        """清除跨批次的 CUSUM 與 Temporal 狀態。"""        # 每個 z 特徵各自保存正向與負向 CUSUM。        self.cusum_pos_state = {}        # 清空「正向累積值」(空字典)        self.cusum_neg_state = {}        # 清空「負向累積值」        self.cusum_initialized = set()   # 清空「哪些特徵已初始化」的標記(空集合)            # 對每個要算 temporal 的特徵 feature_name,建一個空清單 []        self.temporal_history = {            feature_name: []            for feature_name            in self.temporal_base_features        }        # ====================    # 反推誰要計算 temporal    # ====================    def _resolve_temporal_base_features(self):        """        從正式模型與規則欄位反推真正需要的 Temporal Raw feature。            公式全部保留，但 Runtime 只對本版模型實際需要的特徵執行。        """        # 列出所有 temporal 特徵的「前綴」        temporal_prefixes = (            "delta_prev3mean_",            "delta_prev5mean_",            "rolling_max_gap3_",            "rolling_max_gap5_",            "rolling_slope3_",            "rolling_slope5_",            "rolling_std3_",            "rolling_std5_",            "local_rel3_",            "local_rel5_",            "local_z3_",            "local_z5_",            "delta_",        )        # 準備裝「需要算 temporal 的底層特徵」        required = []        # 模型要的 + 規則要的所有欄位,合起來一起檢查        requested_features = (list(self.model_feature_names) + list(self.rule_feature_names))            # 逐個檢查要的欄位        for feature_name in requested_features:            # 先把 CUSUM 排除：CUSUM 不是 Temporal feature，交由 _update_cusum_features() 處理。            if (feature_name.startswith("cusum_pos_") or feature_name.startswith("cusum_neg_")):                continue            # 拿這個欄位去比對每個 temporal 前綴            for prefix in temporal_prefixes:                # 如果它以某個 temporal 前綴開頭                if feature_name.startswith(prefix):                    # 去掉前綴,得到底層特徵名                    raw_name = feature_name[len(prefix):]                        if raw_name not in required:                        required.append(raw_name)                    break            return required     # 回傳「需要算 temporal 的底層特徵清單」        # ====================    # 反推「底層要算哪些 band 能量」    # ====================    def _build_required_extractor_features(self):        """        從「模型+規則要的高階特徵」,反推出「最底層到底要算哪些 band、哪些通道的能量」,好交給濾波那站(extract_required_window_features)只算這些、不多算。        """        # 1.先處理 raw_base_features(排除 summary)        # 「摘要」欄位名的集合        summary_feature_names = set(self.SUMMARY_BASE_COLUMNS)            # 開始收集「底層要算的東西」。這裡先放 raw_base_features(模型要的底層特徵),但排除掉 summary        # 因為 summary(像 offband_E_mean)不是「某一個 band 濾波直接算得出來」的——它是「一堆 band 併起來」的產物,        required = {            feature_name for feature_name in self.raw_base_features            if feature_name not in summary_feature_names        }                # 2.把要的特徵「正規化」(去 rel_/z_ 前綴)        # requested_features:模型 + 規則要的所有欄位。        requested_features = {            str(feature_name)            for feature_name in (list(self.model_feature_names) + list(self.rule_feature_names))        }        # normalized_requested:準備一個「正規化後」的集合。        normalized_requested = set()            for feature_name in requested_features:            # 把原本的欄位名放進去            normalized_requested.add(feature_name)            # 去前綴            if feature_name.startswith("rel_"):                normalized_requested.add(feature_name[len("rel_"):])                elif feature_name.startswith("z_"):                normalized_requested.add(feature_name[len("z_"):])                        # 3.判斷「用到哪些頻帶群組」        # 檢查:正規化後的特徵名裡,有沒有任何一個提到 offband / leak_focus / resonance        needs_offband_energy = any("offband" in feature_name.lower() for feature_name in normalized_requested)        needs_leak_focus_energy = any("leak_focus" in feature_name.lower() for feature_name in normalized_requested)        needs_resonance_energy = any("resonance" in feature_name.lower() for feature_name in normalized_requested)            # 4.一旦需要,就把那個群組「所有 band」加進來        band_config = self.runtime_cfg["band_config"]            # 如果需要 leak_focus 能量,就把 leak_focused_bands 裡的每一個 band、三個通道(ai0/ai1/diff)的能量欄位全部加進 required        if needs_leak_focus_energy:            for band in (band_config.leak_focused_bands):                band_name = str(band["name"])                    required.update(                    {                        f"{band_name}_ai0_E",                        f"{band_name}_ai1_E",                        f"{band_name}_diff_E",                    }                )            # 如果需要 resonance,把 resonance 那組 band 全加進來(三通道)        if needs_resonance_energy:            for band in (band_config.resonance_bands):                band_name = str(band["name"])                    required.update(                    {                        f"{band_name}_ai0_E",                        f"{band_name}_ai1_E",                        f"{band_name}_diff_E",                    }                )            # 如果需要 offband,把 offband 那組 band 加進來        # Offband 在正式特徵工程中只建立 ai0 與 ai1 能量。        if needs_offband_energy:            for band in (band_config.offband_bands):                band_name = str(band["name"])                    required.update(                    {                        f"{band_name}_ai0_E",                        f"{band_name}_ai1_E",                    }                )            return sorted(required)      # 把收集好的集合排序後回傳                # ====================    # ⑤ 累積型偵測(跨批記憶)    # ====================    def _update_cusum_features(        self,        df,    ):        """        使用前一次保存的 CUSUM 狀態，只更新本批新增 Window。        CUSUM 是「累積和」——它不是看單一窗,而是看「z 值持續偏高有沒有累積起來」。關鍵是這個累積要跨批延續        它吃的是上一站算出來的 z_ 值(偏離正常幾個標準差)。做法:         - 每個窗看 z 值超過一個門檻 k 多少,把超出的部分累加起來         - 持續超標 → 累積越來越大 → 偵測到異常         - 為了不讓「很久以前的偏高」永遠留著,每次累加前會先把舊的累積值打個折(衰減 decay),讓遠古的影響慢慢淡出        分兩個方向:cusum_pos(往上偏的累積)、cusum_neg(往下偏的累積)。你的模型特徵 cusum_pos_z_scan_094_..._RMS 就是這麼來的。                        計算方式與離線 add_cusum_features()保持一致。                二、「跨批」為什麼是關鍵        CUSUM 是累積,累積就必須連續。但你的資料是一批一批來的。如果每批都把累積歸零重算,那「持續偏高」的累積就永遠斷在批的邊界,測不出來。        所以 CUSUM 的累積值必須跨批保留——這批算到的累積值,要存起來,下一批接著累加。這就是這個 method 的核心,也是它跟第一站(去DC)那種「當批自足」method 最大的不同。        """        # 只有 z 值超過門檻 k 的部分,才會被累加進 CUSUM。 而且累加的還不是整個 z 值,是「超出門檻的那一截」(z − k),不是 z 本身        cusum_k = float(self.runtime_cfg["cusum_k"])        # 衰減係數(0~1之間)。舊累積值每次先乘它,讓遠古影響淡出        cusum_decay = float(self.runtime_cfg["cusum_decay"])            # z_base_features 哪些 z 特徵要做 CUSUM 的清單        for z_feature in self.z_base_features:            # 防呆:這個 z 欄位在表裡嗎?(            if z_feature not in df.columns:                raise ValueError(f"CUSUM 缺少輸入欄位：{z_feature}")                            # pos_result/neg_result:準備裝這批每個窗算出來的 CUSUM 值            pos_result = []            neg_result = []                        # z_values:把這批所有窗的 z 值取出來,變成一個數字陣列,準備逐窗跑            z_values = pd.to_numeric(df[z_feature], errors="coerce",).fillna(0.0).to_numpy(dtype=np.float64)                # 逐窗跑這批的每個 z 值(這個迴圈是照時間順序的)            for current_z in z_values:                # 與離線版本一致：每條新 Session 的第一個 Window CUSUM 初始值為 0。                if (z_feature not in self.cusum_initialized):                    current_pos = 0.0      # 這條串流的第一個窗，從 0 開始                    current_neg = 0.0                    self.cusum_initialized.add(z_feature)                                    # 不是第一個窗(常態情況):讀出上一次存的累積值                else:                    previous_pos = (self.cusum_pos_state[z_feature])                    previous_neg = (self.cusum_neg_state[z_feature])                        # 計算窗的增量                    positive_increment = max(0.0,float(current_z) - cusum_k,)     # z 值超過門檻 k 多少。max(0, ...) 保證不超標就是 0(不累加負的)                    negative_increment = max(0.0, -float(current_z) - cusum_k,)   # z 值往下超過門檻多少(-current_z - k,偵測往下偏的)                        # 核心公式:新累積 = 舊累積 × 衰減 + 這窗的增量                    # 舊的先打折(decay × previous)→ 遠古影響淡出 -> 加上這窗新的超標量 -> 持續超標 → 一直有增量進來 → 累積往上爬                    current_pos = (cusum_decay * previous_pos + positive_increment)                    current_neg = (cusum_decay * previous_neg + negative_increment)                                    # 記憶動作：把這窗算完的累積值存回 self。這樣下一個窗(或下一批的第一個窗)就能接著用                self.cusum_pos_state[z_feature] = current_pos                self.cusum_neg_state[z_feature] = current_neg                                # 把這窗的累積值記進結果清單                pos_result.append(current_pos)                neg_result.append(current_neg)            # 這批所有窗跑完後,把累積值寫回 df,變成兩個新欄位 cusum_pos_xxx、cusum_neg_xxx            df[f"cusum_pos_{z_feature}"] = pos_result            df[f"cusum_neg_{z_feature}"] = neg_result        # ====================    # ⑥ 看最近幾窗的趨勢(跨批記憶)    # ====================    def _update_temporal_features(        self,        df,    ):        """        使用最近 3～5 個 Window 的歷史，拿來算「趨勢」，只替本批新 Window 建立 Temporal。            支援：         - delta :這個窗比上一個窗高多少/低多少(瞬間變化)         - delta_prev3mean / delta_prev5mean         - local_rel3 / local_rel5 :這個窗相對「最近幾窗的平均」偏離多少         - local_z3 / local_z5         - rolling_std3 / rolling_std5 :最近幾個窗的波動大不大(抖不抖)         - rolling_slope3 / rolling_slope5 :最近幾個窗是往上爬還是往下掉(趨勢斜率)         - rolling_max_gap3 / rolling_max_gap5        """        # 如果沒有任何特徵需要算 temporal,直接跳過整個 method        if not self.temporal_base_features:            return        # 逐窗跑        for row_index in df.index:            # 每個要算 temporal 的特徵            for feature_name in (self.temporal_base_features):                if feature_name not in df.columns:                    raise ValueError(f"Temporal 缺少 Raw 輸入：{feature_name}")                                    # 把「這個窗、這個特徵」的當前值取出來(轉成數字,取不到就 NaN)                current_value = pd.to_numeric(pd.Series([df.at[row_index, feature_name]]),errors="coerce",).iloc[0]                    if pd.isna(current_value):                    current_value = np.nan                else:                    current_value = float(current_value)                # 記憶讀取：讀跨批歷史，這個特徵最近幾個窗的值                history = list(self.temporal_history[feature_name])                    # ------------------------------------                # 計算 delta：當前 Window 相對上一個 Window                # ------------------------------------                # 防呆:得有至少 1 個歷史值、當前值和上一窗值都不是 NaN,才算得出 delta;否則給 NaN                if (len(history) >= 1 and np.isfinite(current_value) and np.isfinite(history[-1])):                         # delta = 當前值 − 上一窗值,就是「跟上一窗比,變了多少」                    delta_value = (current_value - history[-1])     # history[-1] 是上一個窗的值                else:                    delta_value = np.nan                    df.at[row_index,f"delta_{feature_name}"] = delta_value                    # ------------------------------------                # 計算各種趨勢：回看前 3 與前 5 個 Window                # ------------------------------------                # 同樣的計算做兩次,一次看最近 3 窗、一次看最近 5 窗                for window_count in (3, 5):                    # 取最近的歷史值：history[-window_count:]：取最近 3(或 5)個歷史值                    previous_values = np.asarray(history[-window_count:], dtype=np.float64,)                    # 只留有效值(去掉 NaN)                    valid_previous = (previous_values[np.isfinite(previous_values)])                        # local_rel / delta_prevNmean：當前值 - 前幾窗的平均 = 「相對最近水準偏離多少」                    if (len(valid_previous) >= 1 and np.isfinite(current_value)):                        previous_mean = float(np.mean(valid_previous))                        relative_value = (current_value - previous_mean)                    else:                        relative_value = np.nan                        df.at[row_index,                        (                            f"delta_prev"                            f"{window_count}"                            f"mean_{feature_name}"                        ),                    ] = relative_value                        df.at[row_index,                        (                            f"local_rel"                            f"{window_count}_"                            f"{feature_name}"                        ),                    ] = relative_value                        # local_z：上面那個偏離，再除以最近幾窗的標準差 -> 偏離量 ÷ 最近幾窗的波動 = 「以最近的波動當尺,偏離幾倍」                    if (len(valid_previous) >= 2 and np.isfinite(current_value)):                        previous_std = float(np.std(valid_previous, ddof=1,))                        local_z = (relative_value / (previous_std + 1e-12))                    else:                        local_z = np.nan                        df.at[                        row_index,                        (                            f"local_z"                            f"{window_count}_"                            f"{feature_name}"                        ),                    ] = local_z                        # rolling 系列：包含當前窗在內的最近幾窗                    # rolling_values 是「前幾窗 + 當前窗」                    rolling_values = np.asarray((history[-(window_count - 1):] + [current_value]),dtype=np.float64)                    valid_rolling = (rolling_values[np.isfinite(rolling_values)])                        # rolling_std：最近幾窗（含當前）的波動                    if len(valid_rolling) >= 2:                        rolling_std = float(np.std(valid_rolling, ddof=1,))                    else:                        rolling_std = np.nan                                            # rolling_max_gap 跟近期最高差多少：當前值 - 最近幾窗最大值                    if (len(valid_rolling) >= 1 and np.isfinite(current_value)):                        rolling_max_gap = (current_value - float(np.max(valid_rolling)))                    else:                        rolling_max_gap = np.nan                                        # rolling_slope 趨勢斜率：最近幾窗的趨勢斜率                    rolling_slope = (self._calculate_rolling_slope(rolling_values))                        df.at[row_index,                        (                            f"rolling_std"                            f"{window_count}_"                            f"{feature_name}"                        ),] = rolling_std                        df.at[row_index,                        (                            f"rolling_max_gap"                            f"{window_count}_"                            f"{feature_name}"                        ),] = rolling_max_gap                        df.at[row_index,                        (                            f"rolling_slope"                            f"{window_count}_"                            f"{feature_name}"                        ),] = rolling_slope                    # 更新歷史，只保留最近 5 個值。                history.append(current_value)                    self.temporal_history[feature_name] = history[-5:]        # ====================    # 計算趨勢斜率    # ====================    @staticmethod    def _calculate_rolling_slope(        values,    ):        """計算最近數個 Window 的線性趨勢，把「這幾個窗在往哪個方向走、走多快」濃縮成一個數字。"""        # 把傳進來的數字轉成 numpy 的 float64 陣列        values = np.asarray(values, dtype=np.float64,)        # 標記哪些是有效值        finite_mask = np.isfinite(values)                # 數「有幾個 True」(有幾個有效值)。如果有效值少於 2 個(兩點才能決定一條直線),直接回 NaN        if finite_mask.sum() < 2:            return np.nan        # 建立 x 座標(「第幾個窗」):同樣只留有效值        x_values = np.arange(len(values), dtype=np.float64,)[finite_mask]        # y 座標(實際的值):同樣只留有效值        y_values = values[finite_mask]            return float(np.polyfit(x_values, y_values, 1,)[0])#                                                   ****************************************************#                                                        第三層：把第二層包起來,再加上「模型推論」和「暖機管理」#                                                   ****************************************************class StreamingRuntimeEngine:    """    串流模型推論引擎。    負責：    1. 呼叫 StreamingFeatureEngine。    2. 只取得本批新增 Window 的特徵。    3. 模型只預測本批新增 Window。    4. 保存最新機率與累積 Window 數量。    5. 管理啟動暖機時間。    下一階段才接：    - Two-stage    - Veto    - 最短告警時間    - 最終 normal／disturbance／leak 狀態    """    # ====================    # 建立引擎、包住第二層    # ====================    def __init__(        self,        *,        runtime_cfg,        model_bundle,        warmup_sec=5.0,        record_id="live_stream",    ):        self.runtime_cfg = runtime_cfg          # 全部的 runtime 設定        self.model_bundle = model_bundle        # 模型本體(訓練好的 XGBoost + 門檻等)        self.warmup_sec = float(warmup_sec)     # 暖機秒數,預設 5 秒(等下 buffer_ready 會用)        # 建一個第二層(StreamingFeatureEngine)        # StreamingRuntimeEngine（第三層，這個）        #   └── self.feature_engine = StreamingFeatureEngine（第二層）        #         └── self.window_assembler = StreamingWindowAssembler（第一層）        self.feature_engine = (StreamingFeatureEngine(runtime_cfg=runtime_cfg,record_id=record_id,))                self.model_feature_names = list(runtime_cfg["model_feature_names"])     # 模型要吃哪些特徵        self.score_col = runtime_cfg["score_col"]                               # 分數欄位的名字(模型算出的機率要存在哪一欄,例如 leak_score)        self.pred_col = runtime_cfg["pred_col"]                                 # 預測標籤欄位的名字(0/1 存在哪一欄,例如 pred_label)        # 初始化「模型輸出狀態」(下一則會看到這個 method,清空累積窗數、最近分數等)        self.reset_prediction_state()            @property    # 串流跑多久了    def elapsed_sec(self):        return (            self.feature_engine.elapsed_sec        )    # 暖機完成了沒    @property    def buffer_ready(self):        """        是否已經完成啟動暖機。        暖機期間仍會計算特徵與模型機率，只是暫時不對前端發出正式告警。        """        # 判斷:串流跑的時間 ≥ 暖機秒數了嗎? 是就回 True(暖機完成)。        return (self.elapsed_sec >= self.warmup_sec)        # 尾巴保留多少秒    @property    def raw_tail_sec(self):        return (self.feature_engine.raw_tail_sec)    # ====================    # 清空「模型輸出」的狀態    # ====================    def reset_prediction_state(self):        """清除模型輸出狀態。"""        # 累計預測過幾個窗,歸零。這是個計數器,從開機到現在模型總共預測了多少窗        self.total_predicted_windows = 0        # 最近一批的預測結果,設成空的 DataFrame        self.latest_prediction_df = (pd.DataFrame())        # 最近的分數清單,清空        # 回想 process_chunk 裡:self.recent_scores = self.recent_scores[-200:]——它只留最近 200 個分數,給前端畫圖用的。        self.recent_scores = []    # ====================    # 第三層的總重置(重連時真正被呼叫的)    # ====================    def reset(self):        """        開始新的即時監測 Session。        清除：        - Raw Window tail        - CUSUM        - Temporal history        - 模型機率歷史        不會重新載入模型或修改 Site Baseline。         - 模型(model_bundle):模型是訓練好的、固定的,重連又不會讓模型變笨,不用重載(重載還很慢)。         - Site Baseline:正常基準是事先算好、鎖死的,正常還是正常,重連不該動它。        """        # 呼叫第二層的 reset。而第二層的 reset ,它會:        #   - window_assembler.reset()(清第一層:尾巴訊號、切窗計數器)        #   - _reset_derived_feature_state()(清第二層:CUSUM、temporal 歷史)        self.feature_engine.reset()                # 清第三層自己的輸出狀態(上面那個:累計窗數、最近分數等)        '''        第三層 reset()          ├── self.feature_engine.reset()          ← 呼叫第二層          │     ├── self.window_assembler.reset()  ← 呼叫第一層          │     │     └── 清：pending 尾巴、切窗計數器、window_index          │     └── self._reset_derived_feature_state()          │           └── 清：CUSUM 累積、temporal 歷史          └── self.reset_prediction_state()        ← 清第三層自己                └── 清：累計窗數、最近分數、latest_prediction_df        '''        self.reset_prediction_state()    # ====================    # 第二層算特徵 → 丟給模型算分數 → 更新狀態 → 打包回傳    # ====================    def process_chunk(        self,        ai0,        ai1,    ):        """        只對本批新產生的 Window 執行模型。        暫時回傳內部測試用 dictionary；下一階段加入告警後，再整理成 API 格式。        """        # 1.計時開始 + 叫第二層算特徵        # 記錄整個 process_chunk 開始的時間(最後算「這批總共花多久」用)        start_time = time.perf_counter()                # === 特徵計時 ===        _t0 = time.perf_counter()     # 記特徵開始        # 核心委派——把原始訊號丟給第二層,第二層跑完它那整條加工線(切窗→去DC→濾波→summary→baseline→CUSUM→temporal),回傳一張特徵表        df_features = self.feature_engine.process_chunk(ai0, ai1)        _t_feat = time.perf_counter() - _t0        # 如果第二層回空的(這批訊號還不夠切一個完整窗),第三層直接回傳 None,不往下跑模型        if df_features.empty:            return None                # 2.檢查模型要的特徵齊不齊        # 掃過「模型要的特徵名」(model_feature_names),看有沒有哪個不在特徵表 df_features 的欄位裡。        missing_features = [feature_name for feature_name in self.model_feature_names            if feature_name not in df_features.columns        ]        if missing_features:            raise ValueError(f"串流模型輸入缺少特徵：{missing_features[:20]}")                # 3.丟給模型算分數        # === 模型計時 ===        _t1 = time.perf_counter()      # 模型計時        # 只將本批新增 Window 交給模型。        df_predictions = run_model_inference(            df_features=df_features,            model_bundle=self.model_bundle,            score_col=self.score_col,                                     # 對每個窗算出 leak 機率            pred_col=self.pred_col,                                       # 跟門檻 window_threshold 比,超過就標 1、否則 0            threshold_override=(self.runtime_cfg["window_threshold"]),    # 用設定檔的門檻覆蓋        )                _t_model = time.perf_counter() - _t1        # 這批算了幾個窗        n_new_windows = len(df_predictions)        #print(f"⏱ 特徵={_t_feat*1000:.0f}ms  模型={_t_model*1000:.0f}ms  窗數={n_new_windows}")        # 4.更新狀態 + 打包回傳        self.total_predicted_windows += (n_new_windows)      # 累計預測窗數 += 這批的窗數        self.latest_prediction_df = (df_predictions.copy())  # 存下這批的預測表(.copy() 拷一份,避免之後被改到)        # 把這批的分數欄取出來,轉成數字清單        new_scores = pd.to_numeric(df_predictions[self.score_col], errors="coerce",).fillna(0.0).tolist()        # 把這批分數接到「最近分數」後面        self.recent_scores.extend(new_scores)        # 前端最多只需要最近200個機率。        self.recent_scores = (self.recent_scores[-200:])        # 打包成 dict 回傳        calculation_time = (time.perf_counter() - start_time)     # 用最開始的 start_time 算「這批總共花多久」(特徵+模型+雜項全包)        return {            # 目前保留 DataFrame 供開發測試。            # 接 API 前會轉成純 JSON 結果。            "df_features": df_features,            "df_predictions": df_predictions,      # 每窗的分數和 0/1            "n_new_windows": n_new_windows,        # 這批幾個窗            "total_predicted_windows": (self.total_predicted_windows),            "new_scores": new_scores,            "recent_scores": list(self.recent_scores),            # 暖機狀態三兄弟,前端顯示「暖機中/正常」用            "buffer_ready": (self.buffer_ready),            "buffer_sec_current": round(min(self.elapsed_sec, self.warmup_sec,),2,),            "buffer_sec_target": (self.warmup_sec),            # 這批算多久(你算累積落後 stream_lag_sec 時用的就是它)            "calc_time_sec": round(calculation_time,3,),        }                        if __name__ == "__main__":    from pathlib import Path    from runtime_inference import (        load_runtime_configs,        load_model_bundle,    )    BASE_DIR = Path(__file__).resolve().parent    MODEL_DIR = (BASE_DIR / "test_result" / ("saved_models_""transition_disturbance_final") / "xgb" / "xgb_20260909_132257")    runtime_cfg = load_runtime_configs(        band_config_path=(BASE_DIR / "test_result" / "band_config_step2.json"),        feature_config_path=(BASE_DIR / "test_result" / "feature_config_micro.json"),        postprocess_config_path=(MODEL_DIR / "postprocess_config.json"),        runtime_feature_schema_path=(MODEL_DIR / "runtime_feature_schema.json"),        site_baseline_path=(BASE_DIR / "test_result" / "site_baseline.json"),    )        model_bundle = load_model_bundle(MODEL_DIR / "metadata.json")    engine = StreamingRuntimeEngine(        runtime_cfg=runtime_cfg,        model_bundle=model_bundle,        warmup_sec=5.0,    )    fs = int(runtime_cfg["fs"])    capture_sec = 0.5    n_samples = int(fs * capture_sec)    # 暫時使用隨機訊號測試程式結構。    rng = np.random.default_rng(42)    # --------------------------------------------    # 第一批0.5秒訊號    # --------------------------------------------    ai0_first = rng.normal(0.0, 0.01,n_samples,)    ai1_first = rng.normal(0.0, 0.01, n_samples,)    result_first = engine.process_chunk(ai0_first,ai1_first,)    # --------------------------------------------    # 第二批0.5秒訊號    # --------------------------------------------    ai0_second = rng.normal(0.0, 0.01, n_samples,)    ai1_second = rng.normal(0.0, 0.01, n_samples,)    result_second = engine.process_chunk(ai0_second, ai1_second,)    # --------------------------------------------    # 模型增量推論結果    # --------------------------------------------    print("第一批模型預測 Window：", result_first["n_new_windows"],)    print("第二批模型預測 Window：", result_second["n_new_windows"],)    print("模型累積預測 Window：", result_second["total_predicted_windows"],)    print("第一批機率數量：", len(result_first["new_scores"]),)    print("第二批機率數量：", len(result_second["new_scores"]),)    print("目前累積秒數：", engine.elapsed_sec,)    print("暖機完成：", engine.buffer_ready,)    print("第一批耗時：", result_first["calc_time_sec"],)    print("第二批耗時：", result_second["calc_time_sec"],)    # --------------------------------------------    # 特徵欄位完整性檢查    # --------------------------------------------    df_features_first = result_first["df_features"]    df_features_second = result_second["df_features"]    missing_first = [        feature_name for feature_name in runtime_cfg["model_feature_names"]        if feature_name not in df_features_first.columns    ]    missing_second = [        feature_name for feature_name in runtime_cfg["model_feature_names"]        if feature_name not in df_features_second.columns    ]    print("第一批缺少模型特徵：", missing_first,)    print("第二批缺少模型特徵：", missing_second,)    print("需要的 CUSUM：", runtime_cfg["z_base_features"],)    for z_feature in runtime_cfg["z_base_features"]:        cusum_column = (f"cusum_pos_{z_feature}")        print(cusum_column, "第一批最後值=", df_features_first[cusum_column].iloc[-1],)        print(cusum_column, "第二批第一值=", df_features_second[cusum_column].iloc[0],)    print("Temporal 輸入：", engine.feature_engine.temporal_base_features,)    print("第一批時間起點：",df_features_first["t_start"].tolist(),)    print("第二批時間起點：",df_features_second["t_start"].tolist(),)